import heapq

def dijkstra(graph, start, N):
    dist = [float('inf')] * (N + 1)
    dist[start] = 0
    pq = [(0, start)]
    heapq.heapify(pq)

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, weight in graph[u]:
            if dist[u] + weight < dist[v]:
                dist[v] = dist[u] + weight
                heapq.heappush(pq, (dist[v], v))
    return dist

def solve():
    T = int(input())
    results = []
    for _ in range(T):
        N, K, X, M, S = map(int, input().split())
        graph = {i: [] for i in range(1, N + 1)}

        # Add old roads
        for i in range(1, K):
            for j in range(i + 1, K + 1):
                graph[i].append((j, X))
                graph[j].append((i, X))

        # Add newer roads
        for _ in range(M):
            a, b, c = map(int, input().split())
            graph[a].append((b, c))
            graph[b].append((a, c))

        # Run Dijkstra's algorithm from the starting city S
        distances = dijkstra(graph, S, N)
        results.append(' '.join(map(str, distances[1:])))

    for result in results:
        print(result)

# Call the solve function to execute the code
solve()
